(* Golden vectors for the chunk-44 [Tn_snappy] port: CRC-32C known answers,
   raw Snappy blocks and Snappy frame streams.  Shared the way
   batch_vectors.ml and header_vectors.ml are: NOT listed in test/dune's
   (names ...), so dune links it into every test binary, and nothing but the
   stdlib is used, so it drags in no library.

   THE ORACLE.  Every golden row below was emitted on 2026-08-12 by the
   chunk-44 Rust oracle harness
   (~/Documents/telcoin-ocaml-chunk44-harness/oracle, subcommand
   `emit-snappy`), built against telcoin-network @ 31cc4e90 and pinned by
   that tree's Cargo.lock to snap 1.1.1 (Cargo.lock:11163-11164) and
   bcs 0.1.6 (Cargo.lock:1701-1702).  The rows are the byte output of
   `snap::write::FrameEncoder` and `snap::raw::Encoder` over deterministic
   inputs, plus the harness's own CRC-32C of each input, cross-checked
   against the masked CRC snap itself wrote into every chunk header
   (facts-raw.txt:38-44, all MATCH).

   POSITIVE_CONTROL.  The same harness binary re-derives all seven frozen
   chunk-41 [Batch] rows of test/batch_vectors.ml from its own verbatim
   Batch declaration and compares them byte for byte (`chunk44-oracle
   control`, cargo test positive_control_reproduces_frozen_batch_rows): v1
   through v7 all MATCH.  So the harness that produced the rows below is the
   same one that produced the already-trusted batch column.

   THE STREAMS.  The [streams] table holds hand-built frame streams for the
   take-boundary discriminators and the frame negatives, built to the format
   snap 1.1.1 pins (frame.rs:18,26,31-34; read.rs:123-238) with the CRC-32C
   definition of crc32.rs:35-38,85-111.  Each was replayed through the Rust
   harness before it was trusted here: the accepted ones through
   `chunk44-oracle decode frame <cap> <hex> <expected>` (DECODE-OK) and the
   rejected ones through the same command asserting the exact snap error
   (reverse-gate.txt in the harness directory).

   What the rows pin, row by row:
   - s_empty / s_one_byte / s_hello / s_kat_123456789: the tiny end, where
     the port's literal-only raw encoder is byte-identical to snap's;
   - s_repeat_a_* / s_abc_300 / s_mod251_* / s_zeros_*: backreference
     torture, i.e. Rust-produced 0x00 compressed chunks with 1-byte and
     2-byte offset copy tags that the port's encoder never emits but its
     decoder MUST accept;
   - s_lcg_*: incompressible input, where snap emits 0x01 chunks;
   - the 65535/65536/65537 and 131073 rows: the 65536-byte chunk cap
     (snap/src/lib.rs:97 MAX_BLOCK_SIZE), pinned from both sides.
   [frame_hex] and [raw_hex] are [None] where the oracle omitted the hex
   (its FULL_HEX_LIMIT is 4096 bytes, rows.rs:17); those rows still pin the
   lengths and the CRCs, and the port replays them through the reverse
   gate. *)

(* The deterministic input generators, transcribed from the oracle's
   [Gen::bytes] (oracle/src/rows.rs:65-83).  [Lcg] is the 64-bit LCG of
   Knuth/PCG fame: state <- state * 6364136223846793005 + 1442695040888963407
   (wrapping), byte = (state >> 33) land 0xff. *)
type gen =
  | Literal_hex of string
  | Zeros of int
  | Repeat of int * int
  | Mod251 of int
  | Lcg of int64 * int

type row = {
  name : string;
  gen : gen;
  input_len : int;
  frame_len : int;
  frame_hex : string option;
  raw_len : int;
  raw_hex : string option;
  crc32c : int;
  crc32c_masked : int;
}

(* Bytes go into the buffer through [Buffer.add_uint8], which truncates to 8
   bits instead of failing, so no partial [Char.chr] appears anywhere here.
   The modulus is a non-zero literal, so [mod] is total. *)
let of_bytes n f =
  let buf = Buffer.create (max 16 n) in
  let rec go i =
    if i >= n then Buffer.contents buf
    else begin
      Buffer.add_uint8 buf (f i);
      go (i + 1)
    end
  in
  go 0

let mod251 n = of_bytes n (fun i -> i mod 251)
let zeros n = String.make n '\000'
let repeat b n = of_bytes n (fun _ -> b land 0xff)

let lcg seed n =
  let buf = Buffer.create (max 16 n) in
  let rec go i state =
    if i >= n then Buffer.contents buf
    else
      let state =
        Int64.add (Int64.mul state 6364136223846793005L) 1442695040888963407L
      in
      Buffer.add_uint8 buf
        (Int64.to_int (Int64.logand (Int64.shift_right_logical state 33) 0xffL));
      go (i + 1) state
  in
  go 0 seed

(* Hex to bytes, total and fail-closed like test/hex_bytes.ml: a mistyped
   row surfaces as an empty string and a red test, never as a short one. *)
let unhex s =
  let buf = Buffer.create (String.length s / 2) in
  let nibble c = String.index_opt "0123456789abcdef" c in
  let step acc c =
    Option.bind acc (fun pending ->
        Option.map
          (fun lo ->
            Option.fold ~none:(Some lo)
              ~some:(fun hi ->
                Buffer.add_uint8 buf ((hi * 16) + lo);
                None)
              pending)
          (nibble c))
  in
  Option.fold ~none:""
    ~some:(fun (pending : int option) ->
      Option.fold ~none:(Buffer.contents buf) ~some:(fun (_ : int) -> "") pending)
    (String.fold_left step (Some None) s)

let input_of = function
  | Literal_hex h -> unhex h
  | Zeros n -> zeros n
  | Repeat (b, n) -> repeat b n
  | Mod251 n -> mod251 n
  | Lcg (seed, n) -> lcg seed n

